const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/eachtitle";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "each.test.mjs"), [
  "import { test } from 'vitest'",
  "test.each([{ name: 'alice' }])('greets $name', () => {})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=json", "--outputFile=report.json"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const reportFile = path.join(dir, "report.json");
if (!fs.existsSync(reportFile)) {
  console.error("ERROR: vitest wrote no JSON report (exit " + r.status + ")");
  process.exit(2);
}
const report = JSON.parse(fs.readFileSync(reportFile, "utf8"));
const titles = [];
for (const f of report.testResults || []) for (const a of f.assertionResults || []) titles.push(a.title);
console.log("titles: " + JSON.stringify(titles));
if (titles.length === 1 && titles[0] === "greets alice") {
  console.log("PASS: test.each $name gave the title greets alice");
  process.exit(0);
}
if (titles.length === 1 && titles[0] === "greets 'alice'") {
  console.error("FAIL: test.each $name kept quotes around the string: greets 'alice'");
  process.exit(1);
}
console.error("ERROR: unexpected titles " + JSON.stringify(titles) + " (exit " + r.status + ")");
process.exit(2);

